template <typename T> Modular<T> operator/(const Modular<T>& lhs, const Modular<T>& rhs) { return Modular<T>(lhs) /= rhs; }
template <typename T, typename U> Modular<T> operator/(const Modular<T>& lhs, U rhs) { return Modular<T>(lhs) /= rhs; }
template <typename T, typename U> Modular<T> operator/(U lhs, const Modular<T>& rhs) { return Modular<T>(lhs) /= rhs; }

template<typename T, typename U> Modular<T> power(const Modular<T>& a, const U& b) {
    assert(b >= 0);
    Modular<T> x = a, res = 1;
    U p = b;
    while (p > 0) {
        if (p & 1) res *= x;
        x *= x;
        p >>= 1;
    }
    return res;
}

template <typename T> string to_string(const Modular<T>& number) { return to_string(number()); }
template <typename T> ostream& operator<<(ostream& stream, const Modular<T>& number) { return stream << number(); }
template <typename T> istream& operator>>(istream& stream, Modular<T>& number) {
    typename common_type<typename Modular<T>::Type, int64_t>::type x;
    stream >> x;
    number.value = Modular<T>::normalize(x);
    return stream;
}

using ModType = int;
struct VarMod { static ModType value; };
ModType VarMod::value;
ModType& md = VarMod::value;
using Mint = Modular<VarMod>;

int n, m;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> n >> m >> md;
    vector<Mint> fact = {1};
    vector<Mint> inv_fact = {1};
    auto C = [&](int x, int y) {
        int sz = max(x, y);
        while ((int)fact.size() < sz + 1) {
            fact.push_back(fact.back() * fact.size());
            inv_fact.push_back(1 / fact.back());
        }
        if (y < 0 || y > x) return Mint(0);
        return fact[x] * inv_fact[y] * inv_fact[x - y];
    };
    vector<Mint> ptr_dp(m + 1), ptr_ways(m + 1);
    ptr_ways[0] = 1;
    for (int i = 1; i <= m; i++) {
        for (int j = 0; j < i; j++) {
            int l = j, r = i - 1 - l;
            ptr_ways[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * (l + r + 2);
        }
        for (int j = 0; j < i; j++) {
            int l = j, r = i - 1 - l;
            Mint add = (Mint(l) * (l + 1) + Mint(r) * (r + 1)) / 2;
            ptr_dp[i] += ptr_ways[l] * ptr_ways[r] * C(l + r, l) * add;
            ptr_dp[i] += (ptr_dp[l] * ptr_ways[r] + ptr_dp[r] * ptr_ways[l]) * C(l + r, r) * (l + r + 2);
        }
    }
    vector<vector<Mint>> dp(n + 1, vector<Mint>(m + 1));
    vector<vector<Mint>> ways(n + 1, vector<Mint>(m + 1));
    ways[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s <= min(m, i); s++) {
            if (s == i) {
                dp[i][s] = ptr_dp[s];
                ways[i][s] = ptr_ways[s];
                continue;
            }
            for (int d = 1; d <= s + 1; d++) {
                Mint ft = dp[i - d][s + 1 - d];
                Mint way = ways[i - d][s + 1 - d];
                int add = d - 1;
                ways[i][s] += way * ptr_ways[add] * C(s, add);
                dp[i][s] += (way * ptr_dp[add] + ptr_ways[add] * ft) * C(s, add);
            }
        }
    }
    cout << dp[n][m];
    return 0;
}
